/**
 * Synthetic e-commerce dataset for the Data Analyst work simulation.
 *
 * 100% generated by us — no external or copyrighted source. Deterministic
 * (seeded PRNG) so every candidate sees the same data and the answer key stays
 * valid across versions.
 *
 * Planted, discoverable truths:
 *   1. Revenue declines ~18% in Q4 vs Q3.
 *   2. The North region collapses (a large enterprise segment loss).
 *   3. The "paid_social" acquisition source degrades sharply in Q4.
 *   4. Return rate on Electronics roughly doubles in Q4.
 *   5. Discounts deepen in Q4 without lifting units — margin erosion.
 * Planted data-quality problems:
 *   - ~40 duplicate order rows (exact duplicates of an existing order_id).
 *   - ~55 rows with a missing region ("").
 *   - ~25 rows with negative quantity (bad returns encoding).
 *   - ~18 rows where revenue != quantity * price * (1 - discount).
 *   - Mixed date formats in a slice of rows (DD-MM-YYYY vs YYYY-MM-DD).
 *   - Inconsistent category casing ("electronics" vs "Electronics").
 */

export const DATASET_KEY = "hb-ecommerce-revenue-2024";

export interface OrderRow {
  order_id: string;
  customer_id: string;
  order_date: string;
  product: string;
  category: string;
  region: string;
  quantity: number;
  price: number;
  discount: number;
  revenue: number;
  customer_type: string;
  channel: string;
  returned: string;
  acquisition_source: string;
}

/**
 * Calibration constants for the planted signals. These were tuned so the
 * headline Q4-vs-Q3 revenue decline lands at approximately -18%, matching the
 * scenario briefing given to the candidate.
 */
const SIGNALS = {
  /** Share of Q4 enterprise buyers that churn down to "returning". */
  enterpriseChurn: 0.3,
  /** Share of Q4 North orders reassigned to other regions. */
  northRelocate: 0.2,
  /** Share of Q4 paid_social orders reattributed to cheaper sources. */
  paidSocialChurn: 0.55,
  /** Q4 discount = base + rng * spread. */
  q4DiscountBase: 0.06,
  q4DiscountSpread: 0.18,
} as const;

/** Deterministic mulberry32 PRNG. */
function makeRng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const CATEGORIES = [
  { name: "Electronics", products: ["Wireless Earbuds", "Smart Watch", "Bluetooth Speaker", "Laptop Stand"], base: 4200 },
  { name: "Home", products: ["Ceramic Cookware Set", "Air Purifier", "Table Lamp"], base: 2600 },
  { name: "Apparel", products: ["Running Shoes", "Cotton Jacket", "Formal Shirt"], base: 1900 },
  { name: "Beauty", products: ["Vitamin C Serum", "Hair Dryer", "Gift Set"], base: 1200 },
];

const REGIONS = ["North", "South", "East", "West"];
const CUSTOMER_TYPES = ["new", "returning", "enterprise"];
const CHANNELS = ["web", "mobile_app", "marketplace"];
const SOURCES = ["organic", "paid_search", "paid_social", "email", "referral"];

function pick<T>(rng: () => number, arr: T[]): T {
  return arr[Math.floor(rng() * arr.length)];
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function formatDate(d: Date, style: "iso" | "dmy"): string {
  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  return style === "iso" ? `${yyyy}-${mm}-${dd}` : `${dd}-${mm}-${yyyy}`;
}

/** Q3 = Jul–Sep 2024 (healthy). Q4 = Oct–Dec 2024 (the decline). */
export function generateOrders(): OrderRow[] {
  const rng = makeRng(20240718);
  const rows: OrderRow[] = [];
  let orderSeq = 100000;

  const quarters = [
    { start: Date.UTC(2024, 6, 1), days: 92, orders: 1400, quarter: "Q3" as const },
    { start: Date.UTC(2024, 9, 1), days: 92, orders: 1400, quarter: "Q4" as const },
  ];

  for (const q of quarters) {
    const isQ4 = q.quarter === "Q4";
    for (let i = 0; i < q.orders; i += 1) {
      const dayOffset = Math.floor(rng() * q.days);
      const date = new Date(q.start + dayOffset * 86400000);

      let region = pick(rng, REGIONS);
      // Planted signal: North collapses in Q4 (enterprise churn).
      if (isQ4 && region === "North" && rng() < SIGNALS.northRelocate) {
        region = pick(rng, ["South", "East", "West"]);
      }

      let source = pick(rng, SOURCES);
      // Planted signal: paid_social falls away in Q4.
      if (isQ4 && source === "paid_social" && rng() < SIGNALS.paidSocialChurn) {
        source = pick(rng, ["organic", "email"]);
      }

      const category = pick(rng, CATEGORIES);
      const product = pick(rng, category.products);

      let customerType = pick(rng, CUSTOMER_TYPES);
      // Enterprise buyers concentrate in North and mostly vanish in Q4.
      if (customerType === "enterprise" && isQ4 && rng() < SIGNALS.enterpriseChurn) customerType = "returning";
      if (customerType === "enterprise") region = rng() < 0.75 ? "North" : region;

      const quantity =
        customerType === "enterprise"
          ? 4 + Math.floor(rng() * 9)
          : 1 + Math.floor(rng() * 3);

      const price = round2(category.base * (0.75 + rng() * 0.5));

      // Planted signal: deeper discounting in Q4 that does not lift volume.
      const discount = isQ4
        ? round2(Math.min(0.45, SIGNALS.q4DiscountBase + rng() * SIGNALS.q4DiscountSpread))
        : round2(rng() * 0.15);

      const revenue = round2(quantity * price * (1 - discount));

      // Planted signal: Electronics returns roughly double in Q4.
      const returnChance =
        category.name === "Electronics" ? (isQ4 ? 0.17 : 0.08) : isQ4 ? 0.07 : 0.05;
      const returned = rng() < returnChance ? "Yes" : "No";

      rows.push({
        order_id: `ORD-${orderSeq++}`,
        customer_id: `CUST-${1000 + Math.floor(rng() * 900)}`,
        order_date: formatDate(date, "iso"),
        product,
        // Planted quality problem: inconsistent casing on a slice of rows.
        category: rng() < 0.06 ? category.name.toLowerCase() : category.name,
        region,
        quantity,
        price,
        discount,
        revenue,
        customer_type: customerType,
        channel: pick(rng, CHANNELS),
        returned,
        acquisition_source: source,
      });
    }
  }

  // ── Planted data-quality problems ───────────────────────────────────────
  // Missing region
  for (let i = 0; i < 55; i += 1) {
    rows[Math.floor(rng() * rows.length)].region = "";
  }
  // Negative quantity (bad return encoding)
  for (let i = 0; i < 25; i += 1) {
    const row = rows[Math.floor(rng() * rows.length)];
    row.quantity = -Math.abs(row.quantity);
    row.revenue = round2(row.quantity * row.price * (1 - row.discount));
  }
  // Revenue that does not reconcile with quantity * price * (1 - discount)
  for (let i = 0; i < 18; i += 1) {
    const row = rows[Math.floor(rng() * rows.length)];
    row.revenue = round2(row.revenue * (1.4 + rng()));
  }
  // Mixed date formats
  for (let i = 0; i < 70; i += 1) {
    const row = rows[Math.floor(rng() * rows.length)];
    const [y, m, d] = row.order_date.split("-");
    if (y.length === 4) row.order_date = `${d}-${m}-${y}`;
  }
  // Exact duplicate rows
  const duplicates: OrderRow[] = [];
  for (let i = 0; i < 40; i += 1) {
    duplicates.push({ ...rows[Math.floor(rng() * rows.length)] });
  }
  rows.push(...duplicates);

  return rows;
}

export const DATASET_COLUMNS: (keyof OrderRow)[] = [
  "order_id",
  "customer_id",
  "order_date",
  "product",
  "category",
  "region",
  "quantity",
  "price",
  "discount",
  "revenue",
  "customer_type",
  "channel",
  "returned",
  "acquisition_source",
];

export function toCsv(rows: OrderRow[]): string {
  const header = DATASET_COLUMNS.join(",");
  const body = rows
    .map((row) =>
      DATASET_COLUMNS.map((col) => {
        const value = row[col];
        const text = String(value);
        return text.includes(",") ? `"${text}"` : text;
      }).join(","),
    )
    .join("\n");
  return `${header}\n${body}\n`;
}

/** A small preview for the in-browser data grid. */
export function previewRows(limit = 25): OrderRow[] {
  return generateOrders().slice(0, limit);
}

export interface DatasetFacts {
  totalRows: number;
  duplicateRows: number;
  missingRegionRows: number;
  negativeQuantityRows: number;
  q3Revenue: number;
  q4Revenue: number;
  revenueChangePct: number;
}

/** Ground-truth facts, computed from the generated data (never hardcoded). */
export function computeDatasetFacts(rows: OrderRow[] = generateOrders()): DatasetFacts {
  const seen = new Set<string>();
  let duplicateRows = 0;
  let missingRegionRows = 0;
  let negativeQuantityRows = 0;
  let q3Revenue = 0;
  let q4Revenue = 0;

  for (const row of rows) {
    const fingerprint = DATASET_COLUMNS.map((c) => String(row[c])).join("|");
    if (seen.has(fingerprint)) duplicateRows += 1;
    seen.add(fingerprint);

    if (row.region === "") missingRegionRows += 1;
    if (row.quantity < 0) negativeQuantityRows += 1;

    const month = parseMonth(row.order_date);
    if (month >= 7 && month <= 9) q3Revenue += row.revenue;
    else if (month >= 10) q4Revenue += row.revenue;
  }

  return {
    totalRows: rows.length,
    duplicateRows,
    missingRegionRows,
    negativeQuantityRows,
    q3Revenue: Math.round(q3Revenue),
    q4Revenue: Math.round(q4Revenue),
    revenueChangePct: q3Revenue === 0 ? 0 : round2(((q4Revenue - q3Revenue) / q3Revenue) * 100),
  };
}

function parseMonth(dateText: string): number {
  const parts = dateText.split("-");
  // ISO (YYYY-MM-DD) vs DMY (DD-MM-YYYY)
  return parts[0].length === 4 ? Number(parts[1]) : Number(parts[1]);
}
